const loaderDuration = "1.65s"

export interface VetorthoplanLoaderProps {
  className?: string
  size?: number
}

export function VetorthoplanLoader({
  className,
  size = 88,
}: VetorthoplanLoaderProps) {
  const style = {
    "--loader-duration": loaderDuration,
    "--loader-size": `${size}px`,
  } as CSSProperties

  return (
    <span
      aria-label="Carregando"
      aria-live="polite"
      className={cn(styles.loader, className)}
      role="status"
      style={style}
    >
      <span aria-hidden="true" className={styles.assembly}>
        <svg
          className={styles.symbol}
          fill="none"
          preserveAspectRatio="xMidYMid meet"
          viewBox="0 0 1500 1500"
          xmlns="http://www.w3.org/2000/svg"
          dangerouslySetInnerHTML={{ __html: symbolPaths }}
        />
      </span>
    </span>
  )
}
